--
-- Estructura para la vista `readable_cheatlog`
--
DROP TABLE IF EXISTS `readable_cheatlog`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `readable_cheatlog`  AS  select `a`.`name` AS `accountname`,`a`.`id` AS `accountid`,`c`.`name` AS `name`,`c`.`id` AS `characterid`,`cl`.`offense` AS `offense`,`cl`.`count` AS `count`,`cl`.`lastoffensetime` AS `lastoffensetime`,`cl`.`param` AS `param` from ((`cheatlog` `cl` join `characters` `c`) join `accounts` `a`) where `cl`.`id` = `c`.`id` and `a`.`id` = `c`.`accountid` and `a`.`banned` = 0 ;

-- --------------------------------------------------------

--
-- Estructura para la vista `readable_last_hour_cheatlog`
--
DROP TABLE IF EXISTS `readable_last_hour_cheatlog`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `readable_last_hour_cheatlog`  AS  select `a`.`name` AS `accountname`,`a`.`id` AS `accountid`,`c`.`name` AS `name`,`c`.`id` AS `characterid`,sum(`cl`.`count`) AS `numrepos` from ((`cheatlog` `cl` join `characters` `c`) join `accounts` `a`) where `cl`.`id` = `c`.`id` and `a`.`id` = `c`.`accountid` and timestampdiff(HOUR,`cl`.`lastoffensetime`,current_timestamp()) < 1 and `a`.`banned` = 0 group by `cl`.`id` order by sum(`cl`.`count`) desc ;

